package com.kavir.store.data

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

val AppJson: Json = Json {
    ignoreUnknownKeys = true
    prettyPrint = true
    encodeDefaults = true
}

/** The public catalog (catalog/apps.json) generated by the sync workflow. */
@Serializable
data class Catalog(
    val schema: Int = 1,
    @SerialName("generated_at") val generatedAt: String = "",
    val apps: List<CatalogApp> = emptyList(),
)

@Serializable
data class CatalogApp(
    val id: String = "",
    val name: String,
    @SerialName("name_fa") val nameFa: String? = null,
    @SerialName("package_name") val packageName: String,
    val description: String = "",
    @SerialName("description_fa") val descriptionFa: String? = null,
    val category: String = "other",
    val icon: String? = null,
    val screenshots: List<String> = emptyList(),
    val repo: String = "",
    @SerialName("repo_url") val repoUrl: String = "",
    val featured: Boolean = false,
    val enabled: Boolean = true,
    val release: Release? = null,
) {
    fun displayName(fa: Boolean): String = if (fa && !nameFa.isNullOrBlank()) nameFa else name
    fun displayDescription(fa: Boolean): String =
        if (fa && !descriptionFa.isNullOrBlank()) descriptionFa else description
}

@Serializable
data class Release(
    val tag: String = "",
    @SerialName("version_name") val versionName: String = "",
    @SerialName("version_code") val versionCode: Long = 0,
    @SerialName("apk_url") val apkUrl: String = "",
    @SerialName("apk_name") val apkName: String = "",
    val size: Long = 0,
    val sha256: String = "",
    @SerialName("min_sdk") val minSdk: Int = 1,
    val changelog: String = "",
    @SerialName("published_at") val publishedAt: String = "",
    val signer: String? = null,
)

/** The editable registry (catalog/sources.json), changed only by the admin panel / repo owner. */
@Serializable
data class Sources(
    val schema: Int = 1,
    val apps: List<SourceApp> = emptyList(),
)

@Serializable
data class SourceApp(
    val repo: String,
    val enabled: Boolean = true,
    val featured: Boolean = false,
    val category: String = "other",
    val name: String? = null,
    @SerialName("name_fa") val nameFa: String? = null,
    val description: String? = null,
    @SerialName("description_fa") val descriptionFa: String? = null,
    val icon: String? = null,
    val screenshots: List<String> = emptyList(),
    @SerialName("asset_pattern") val assetPattern: String? = null,
    val prerelease: Boolean = false,
)

val CATEGORY_IDS = listOf(
    "tools", "games", "social", "media", "productivity", "education", "communication", "other"
)

fun sdkToAndroid(sdk: Int): String = when (sdk) {
    26 -> "8.0"
    27 -> "8.1"
    28 -> "9"
    29 -> "10"
    30 -> "11"
    31 -> "12"
    32 -> "12L"
    33 -> "13"
    34 -> "14"
    35 -> "15"
    36 -> "16"
    else -> if (sdk <= 25) "7.1 or older" else "API $sdk"
}

fun formatSize(bytes: Long): String {
    if (bytes <= 0) return "—"
    val mb = bytes / (1024.0 * 1024.0)
    return if (mb >= 1) String.format(java.util.Locale.US, "%.1f MB", mb)
    else String.format(java.util.Locale.US, "%d KB", (bytes / 1024).coerceAtLeast(1))
}
